const availablePairs=()=>level?.siege?siegePairs(board,siege):null;
const currentHint=()=>(level?.fire||level?.noOuter)?firePairs(board,ids,fire,fog,siege).find(([a,b])=>![...fire.active,...fire.events.filter((e,k)=>!fire.fired.includes(k))].some(e=>e.ids.includes(ids[a])!==e.ids.includes(ids[b]))):(level?.fog||level?.left)?fogPairs(board,fog,siege)[0]:level?.siege?availablePairs()[0]:hint(board);
const chapterLabel=()=>['','第一章','第二章','第三章','第四章','第五章','第六章','第七章','第八章'][chapter];
const $=s=>document.querySelector(s),app=$('#app');
let data,text={},progress={stars:Array(10).fill(0),intro:false},level,board,ids=[],selected=-1,history=[],hints=3,shuffles=2,moves=0,combo=0,maxCombo=0,lastMatch=0,remaining=0,started=0,paused=false,busy=false,screen='',muted=false,run=0,usedHint=false;
const sounds={select:'s1',clear:'s2',bad:'s3',hint:'s4',coin:'s4',shuffle:'s5',win:'s6',start:'s7',lose:'s8',two:'s9',many:'s10'};
const music=createMusic(),effectMusic=createMusic();
document.addEventListener('visibilitychange',()=>{music.visibility();effectMusic.visibility();if(document.hidden)for(const a of Object.values(audio))a.pause();});
const audio={};for(const [k,v]of Object.entries(sounds)){audio[k]=new Audio();audio[k].preload='none';audio[k].soundSrc='sfx/'+v+'.mp3';}
audio.timber=new Audio();audio.timber.preload='none';audio.timber.soundSrc='sfx/'+sounds.two+'.mp3';audio.timber.volume=.14;
function sound(k){if(muted||!settings.sfxEnabled||settings.sfx<=0)return;const a=audio[k];if(!a.src)a.src=a.soundSrc;a.volume=settings.sfx*(k==='timber'?.14:k==='coin'?.18:1);a.currentTime=0;a.play().catch(()=>{});if(k==='select'&&settings.vibration&&typeof navigator!=='undefined')navigator.vibrate?.(8);}
document.addEventListener('click',e=>{if(e.target?.closest?.('button')&&!e.target.closest('.tile'))sound('select');});
function save(){try{localStorage.setItem(`sengoku-ch${chapter}-v1`,JSON.stringify(progress));}catch{toast('記録を保存できません');}}
try{const p=JSON.parse(localStorage.getItem('sengoku-ch1-v1'));if(p&&Array.isArray(p.stars))progress={stars:Array.from({length:10},(_,i)=>Math.min(3,Math.max(0,Number(p.stars[i])||0))),intro:!!p.intro};}catch{}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function person(v){return text.people?.[data.names[v-1]]||{};}function short(v){return person(v).short||['信長','濃姫','秀吉','利家','勝家','長秀','新介','お市','義元','元康','朝比奈','直盛','宗信','直虎'][v-1];}
function portrait(v){if(data.portraits)return data.portraits[v-1];return 'portraits/ch1/'+data.names[v-1]+'.png';}
function targetSpec(t=level.target){return t===true?{person:9,beforePairs:14}:t;}
function targetRule(t=level.target){const x=targetSpec(t);return `第${x.beforePairs}組まで（その組の終了時）に、${short(x.person)}の牌をすべて消せ。`;}
function formation(l){return text.formations?.[l.formation]||{};}
function fname(l){return formation(l).name||l.formation+(l.formation==='総懸かり'?'':'の陣');}
function toast(t){$('#toast').textContent=t;$('#toast').style.opacity=1;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.opacity=0,2200);}
function weatherEmptyCells(){const root=$('.board');if(!root||!board)return [];const rect=root.getBoundingClientRect(),{w,h,gap}=geometry();return board.flatMap((v,i)=>v?[]:[{id:i,x:rect.left+(i%7)*(w+gap)+w/2,y:rect.top+Math.floor(i/7)*(h+gap)+h/2}]);}
function view(html,cls=''){applyCosmetics();document.body.dataset.chapter=chapter;document.body.style.setProperty('--chapter-intro',`url('img/ch${chapter}_intro.jpg'),url('img/ch${Math.max(1,chapter-1)}_intro.jpg'),url('img/ch1_intro.jpg')`);music.stop();effectMusic.stop();music.pause(false);effectMusic.pause(false);weather({battle:cls==='game',paused:false,boss:level?.id===10,silent:muted||!settings.sfxEnabled,chapter,effect:level?.weather?.type,fade:level?.weather?.fade,count:level?.weather?.count,volume:settings.sfx,progress:()=>1-seconds()/level.time,emptyCells:weatherEmptyCells});run++;screen=cls.split(' ')[0];busy=false;app.innerHTML=`<main class="screen ${cls}">${html}</main>`;scrollTo(0,0);}
// 名鑑 uses stable portrait keys, shared across all chapter-local person numbers.
let catalog={people:[],chapters:[]},collected=new Set(),catalogChapter=Number(readJSON('sengoku-catalog-chapter',1))||1;
const CATALOG_KEY='sengoku-catalog-v1';
function loadCollection(){collected=new Set();try{const saved=JSON.parse(localStorage.getItem(CATALOG_KEY));if(Array.isArray(saved?.people))collected=new Set(saved.people.filter(id=>catalog.people.some(p=>p.id===id)));}catch{collected=new Set();}}
function collectDebut(d=data,l=level){let changed=false;for(const v of l.debut){const id=d.names[v-1];if(catalog.people.some(p=>p.id===id)&&!collected.has(id)){collected.add(id);changed=true;}}if(changed)try{localStorage.setItem('sengoku-unread','1');localStorage.setItem(CATALOG_KEY,JSON.stringify({version:1,people:[...collected]}));}catch{toast('名鑑の記録を保存できません');}}
const catalogCount=()=>`${collected.size}/${catalog.people.length}`;
const catalogPerson=id=>catalog.people.find(p=>p.id===id);
function catalogTile(p){const known=collected.has(p.id);return `<button class="catalog-item" data-person="${esc(p.id)}" aria-label="${known?esc(p.name):'未発見の武将'}"><span class="catalog-portrait pc ${known?esc(p.faction):'unknown'}"><img loading="lazy" src="${esc(p.image)}" alt="" ${known?'':'class="silhouette"'}></span><span class="catalog-name">${known?esc(p.name):'？？？'}</span></button>`;}
function collection(){localStorage.setItem('sengoku-collection-tab','people');localStorage.removeItem('sengoku-unread');const groups=catalog.chapters.filter(c=>c.id===catalogChapter);view(`<header class="toolbar"><h2>典藏</h2><button id="catalog-close">閉じる</button></header><nav class="catalog-tabs" aria-label="典藏"><button aria-current="page" id="warrior-tab">武将</button><button id="art-tab">挿絵</button><button id="formation-tab">陣形</button><button id="music-tab">音楽</button></nav><div class="catalog-progress">武将名鑑　<b>${catalogCount()}</b><small>「初登場」で出会った武将を記録します。</small></div><label class="catalog-filter">初登場の章 <button id="catalog-chapter">第${catalogChapter}章 ▾</button></label>${groups.map(c=>{const ps=catalog.people.filter(p=>p.firstChapter===c.id);return `<section><h3>第${c.id}章　${esc(c.name)} <small>${ps.filter(p=>collected.has(p.id)).length}/${ps.length}</small></h3><div class="catalog-grid">${ps.map(catalogTile).join('')}</div></section>`;}).join('')}`,'collection paged');$('#catalog-close').onclick=()=>settingsPage('data');$('#art-tab').onclick=()=>extraCollection('art');$('#music-tab').onclick=()=>extraCollection('music');$('#warrior-tab').onclick=collection;$('#formation-tab').onclick=formationCollection;$('#catalog-chapter').onclick=()=>choiceDialog('初登場の章',catalog.chapters.map(c=>[c.id,'第'+c.id+'章　'+c.name]),v=>{catalogChapter=Number(v);localStorage.setItem('sengoku-catalog-chapter',JSON.stringify(catalogChapter));collection();});document.querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>{if(collected.has(b.dataset.person))personPage(b.dataset.person);else toast('まだ出会っていません');});}
function pager(key,count){let index=Number(readJSON('sengoku-page-'+key,0));if(!Number.isInteger(index)||index<0||index>=count)index=0;return {index,html:`<nav class="btn-row pager"><button id="page-prev" ${index===0?'disabled':''}>前へ</button><span>${index+1} / ${count}</span><button id="page-next" ${index===count-1?'disabled':''}>次へ</button></nav>`,bind(render){for(const [id,delta] of [['page-prev',-1],['page-next',1]])$('#'+id).onclick=()=>{localStorage.setItem('sengoku-page-'+key,JSON.stringify(index+delta));render();};}};}
function formationCollection(){localStorage.removeItem('sengoku-unread');localStorage.setItem('sengoku-collection-tab','formations');const forms=new Map();for(const c of chapters.values())for(const l of c.data.levels)if(!forms.has(l.formation))forms.set(l.formation,{level:l,info:c.text.formations?.[l.formation]||{}});const page=pager('formations',forms.size);view(`<header class="toolbar"><h2>典藏</h2><button id="catalog-close">閉じる</button></header><nav class="catalog-tabs" aria-label="典藏"><button id="warrior-tab">武将</button><button id="art-tab">挿絵</button><button aria-current="page" id="formation-tab">陣形</button><button id="music-tab">音楽</button></nav><p class="muted">本作に登場する陣形。形は代表的な一戦の配置です。</p>${page.html}${[...forms].slice(page.index,page.index+1).map(([name,{level:l,info:f}])=>`<section class="catalog-formation"><h3>${esc(name)}${name==='総懸かり'?'':'の陣'}</h3><div class="muted">${esc(f.kana||'')}</div>${mini(l)}<p>${esc(f.intro||'兵を配し、戦局に合わせて攻めと守りを組み立てる。')}</p></section>`).join('')}`,'collection paged');page.bind(formationCollection);$('#catalog-close').onclick=()=>settingsPage('data');$('#art-tab').onclick=()=>extraCollection('art');$('#music-tab').onclick=()=>extraCollection('music');$('#warrior-tab').onclick=collection;$('#formation-tab').onclick=formationCollection;}

function openCollection(){const tab=localStorage.getItem('sengoku-collection-tab');if(tab==='formations')formationCollection();else if(tab==='art'||tab==='music')extraCollection(tab);else collection();}
function personPage(id,tab){const choices=[['impression','人物'],['reality','史実'],['anecdote','逸話・絆']];tab=savedTab('person',choices,tab);const p=catalogPerson(id);if(!p||!collected.has(id))return;view(`<header class="toolbar"><button id="catalog-back">名鑑へ</button><span class="eyebrow">武将名鑑　${catalogCount()}</span></header><article class="catalog-detail"><div class="catalog-hero pc ${esc(p.faction)}"><img src="${esc(p.image)}" alt="${esc(p.name)}"></div><p class="catalog-kana">${esc(p.kana)}</p><h1>${esc(p.name)}</h1><p>${esc(p.years)}<br><span class="catalog-crest pc ${esc(p.faction)}" role="img" aria-label="${esc(p.crest)}"></span> ${esc(p.family)}　${esc(p.crest)}</p><p class="catalog-epithet">${esc(p.epithet)}</p>${pageTab('person',choices,tab)}<div class="catalog-bio"><p>${esc(p.bio[tab])}</p></div>${tab==='anecdote'?'<h3>絆</h3>':''}<div class="catalog-bonds">${(tab==='anecdote'?p.bonds:[]).map(b=>{const other=catalogPerson(b.person),known=collected.has(b.person);return `<button data-bond="${esc(b.person)}" ${known?'':'disabled'}>${esc(b.type)}：${known?esc(other.name):'？？？（未発見）'}</button>`;}).join('')}</div><p class="muted">初登場：第${p.firstChapter}章・第${p.firstLevel}戦<br>所属・家紋は初登場の章の陣営を表示（簡略図）。</p></article>`,'collection paged person-detail');bindPageTabs('person',t=>personPage(id,t));$('#catalog-back').onclick=collection;document.querySelectorAll('[data-bond]').forEach(b=>b.onclick=()=>personPage(b.dataset.bond));}


let worldMap={provinces:[],levels:[],chapters:[],viewBox:'-190 0 610 605'};
function mapEntry(c=chapter,l=level?.id){return worldMap.levels.find(v=>v.chapter===c&&v.level===l);}
function conquered(){return new Set(worldMap.levels.filter(v=>chapters.get(v.chapter)?.progress.stars[v.level-1]>0).map(v=>v.province).filter(Boolean));}
function unified(){return chapters.size===8&&[...chapters.values()].every(c=>c.progress.stars.every(Boolean));}
let recentOccupation=null;
const mapFaction=c=>c===4?'takeda':c===6?'akechi':c===7?'tokugawa':c===8?'toyotomi':'oda';
function occupationSound(){const token=run;setTimeout(()=>{if(run===token)sound('select');},600);}
function mapSVG(focus='',animate=false,full=false){const owned=conquered(),target=worldMap.provinces.find(p=>p.id===focus),box=target&&!full?`${target.x-65} ${target.y-65} 130 130`:worldMap.viewBox,faction=mapFaction(recentOccupation?.province===focus?recentOccupation.chapter:chapter);return `<svg class="province-map ${animate?'occupation-map':''} ${faction}" viewBox="${box}" role="img" aria-label="旧国地図${focus?'・'+esc(focus):''}"><image href="img/map_japan.svg" x="-190" y="0" width="610" height="605"/>${worldMap.provinces.map(p=>`<path class="province ${owned.has(p.id)?'owned':''} ${focus===p.id?'focused':''} ${animate&&focus===p.id?'occupying':''}" d="${p.d}"><title>${esc(p.name)}${owned.has(p.id)?'・制圧済':''}</title></path>`).join('')}${worldMap.provinces.map(p=>`<text class="province-label" x="${p.x}" y="${p.y+3}">${esc(p.name)}</text>`).join('')}${target?`<g transform="translate(${target.x} ${target.y})"><foreignObject x="-12" y="-12" width="24" height="24" class="${animate?'occupation-seal-drop':''}"><div xmlns="http://www.w3.org/1999/xhtml" class="occupation-seal pc ${faction}" aria-label="家紋印章"></div></foreignObject></g>`:''}</svg>`;}
// Keep the full country visible; the crest is positioned with task 42 coordinates.
function mapLocation(){const bf=(worldMap.chapters||[]).find(c=>c.id===chapter)?.province,e=mapEntry(),p=worldMap.provinces.find(p=>p.id===(bf||e?.province));if(!p)return '';const faction=chapter===4?'takeda':chapter===6?'akechi':chapter===7?'tokugawa':chapter===8?'toyotomi':'oda';return `<button id="mini-map" class="map-location" aria-label="${esc(p.name)}国の位置・天下統一地図を開く"><span class="mini-map-art">${mapSVG()}<i class="mini-map-crest pc ${faction}" style="left:${(p.x+190)/610*100}%;top:${p.y/605*100}%"></i></span><span>本陣：<b>${esc(p.name)}国</b></span></button>`;}
function victoryStamp(){return `<div class="victory-stamp" role="img" aria-label="勝"><svg viewBox="0 0 120 120" aria-hidden="true"><defs><filter id="seal-ink"><feTurbulence type="fractalNoise" baseFrequency=".19" numOctaves="3" seed="8" result="noise"/><feDisplacementMap in="SourceGraphic" in2="noise" scale="1.8"/></filter></defs><g fill="none" stroke="currentColor" stroke-linejoin="round" stroke-linecap="square" filter="url(#seal-ink)"><path stroke-width="5" d="M10 9L110 11 109 110 9 108Z"/><path stroke-width="2" d="M16 16H103V103H16Z"/><!-- Hand-cut square seal strokes for 勝: 月 + upper component + 力. --><path stroke-width="6" d="M25 94V27H46V92H38M26 46H45M26 65H45M57 26L63 37M87 26L81 37M54 43H96M56 55H96M73 37L65 57 53 68M79 44L90 62 98 67M56 72H91L88 93H78M72 61L69 78 58 94"/></g></svg></div>`;}

const MAP_MARKERS=[[80,67],[70,52],[45,42],[88,38],[88,80],[43,63],[56,79],[32,83]];
function selectChapter(){const owned=conquered();view(`<header class="toolbar"><h2>天下統一地図</h2><button id="back">タイトルへ</button></header><div class="map-summary">制圧 ${owned.size} / 66 国　・　${[...chapters.values()].reduce((n,c)=>n+c.progress.stars.filter(Boolean).length,0)} / 80 戦</div><div class="map-controls"><button id="map-minus" aria-label="縮小">−</button><button id="map-reset">全図</button><button id="map-plus" aria-label="拡大">＋</button></div><div class="map-viewport"><div class="map-canvas">${mapSVG(recentOccupation?.province||'',!!recentOccupation,true)}<svg class="map-leaders" viewBox="-190 0 610 605" aria-hidden="true">${worldMap.chapters.map((c,i)=>{const p=worldMap.provinces.find(p=>p.id===c.province),pos=MAP_MARKERS[i];return `<path d="M${p.x},${p.y}L${pos[0]*6.1-190},${pos[1]*6.05}"/><circle cx="${p.x}" cy="${p.y}" r="3"/>`;}).join('')}</svg>${worldMap.chapters.map((c,i)=>{const p=worldMap.provinces.find(p=>p.id===c.province);const pos=MAP_MARKERS[i];return `<button id="ch${c.id}" class="map-marker pc ${c.id===4?'takeda':c.id===6?'akechi':c.id===7?'tokugawa':c.id===8?'toyotomi':'oda'}" style="left:${pos[0]}%;top:${pos[1]}%" aria-label="第${c.id}章 ${esc(c.name)}" ${!UNLOCK_ALL&&!previewAll&&c.id>1&&!chapters.get(c.id-1).progress.stars.every(Boolean)?'disabled':''}><span>${c.id}</span></button>`;}).join('')}</div></div><p class="map-help">家紋をタップして出陣。＋で拡大、指で移動できます。</p><div class="map-chapters">${worldMap.chapters.map(c=>`<button data-map-chapter="${c.id}" ${!UNLOCK_ALL&&!previewAll&&c.id>1&&!chapters.get(c.id-1).progress.stars.every(Boolean)?'disabled':''}>${c.id}　${esc(c.name)}</button>`).join('')}</div>${unified()?'<button id="unified" class="primary">天下統一の記録</button>':''}<details class="map-credit"><summary>地図について・出典</summary><p>戦国期の66国（壱岐・対馬を除く）。進軍順は遊戯上の演出です。</p><a href="https://commons.wikimedia.org/wiki/File:Provinces_of_Japan.svg" target="_blank" rel="noopener">Provinces of Japan — Ash_Crow（原図：百楽兎）</a> · <a href="https://creativecommons.org/licenses/by/2.5/" target="_blank" rel="noopener">CC BY 2.5</a><p>境界を抽出し、配色・構成・表示範囲を変更。</p></details>`,'world-map');for(const c of worldMap.chapters)$('#ch'+c.id).onclick=()=>chooseChapter(c.id);document.querySelectorAll('[data-map-chapter]').forEach(b=>b.onclick=()=>chooseChapter(+b.dataset.mapChapter));$('#back').onclick=title;if($('#unified'))$('#unified').onclick=ending;bindMap();if(recentOccupation)occupationSound();}
function bindMap(){const viewport=$('.map-viewport'),canvas=$('.map-canvas');let zoom=1,drag=null,moved=false;function scale(n){zoom=Math.max(1,Math.min(3,n));canvas.style.width=`${zoom*100}%`;}$('#map-plus').onclick=()=>scale(zoom+.5);$('#map-minus').onclick=()=>scale(zoom-.5);$('#map-reset').onclick=()=>{scale(1);viewport.scrollLeft=viewport.scrollTop=0;};viewport.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,l:viewport.scrollLeft,t:viewport.scrollTop};moved=false;};viewport.onpointermove=e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(dx,dy)>8){moved=true;viewport.setPointerCapture?.(e.pointerId);}if(moved){viewport.scrollLeft=drag.l-dx;viewport.scrollTop=drag.t-dy;}};viewport.onpointerup=viewport.onpointercancel=()=>{drag=null;};viewport.onclick=e=>{if(moved){e.preventDefault();e.stopPropagation();moved=false;}};viewport.addEventListener?.('click',e=>{if(moved){e.preventDefault();e.stopPropagation();moved=false;}},true);}
function chooseChapter(n){if(!UNLOCK_ALL&&!previewAll&&n>1&&!chapters.get(n-1).progress.stars.every(Boolean)){toast('前の章をクリアしてください');return;}if(n>1&&!previewAll&&!store.isUnlocked()){unlockPage(()=>chooseChapter(n));return;}chapters.get(chapter).progress=progress;chapter=n;({data,text,progress}=chapters.get(n));selectLevel();}
function selectLevel(){view(`<div class="eyebrow">${chapterLabel()}</div><h2>${esc(text.chapter?.title||'桶狭間の戦い')}</h2><div class="scroll"><div class="levels">${data.levels.map((l,i)=>`<button class="level" data-level="${i}" ${!UNLOCK_ALL&&!previewAll&&i>0&&!progress.stars[i-1]?'disabled':''}><strong>${i+1}</strong>　${esc(fname(l))}<br><span class="stars">${'★'.repeat(progress.stars[i])}${'☆'.repeat(3-progress.stars[i])}</span></button>`).join('')}</div></div><div class="btn-row"><button id="back">章の選択へ</button><button id="intro">章の紹介</button></div>`);document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>enter(+b.dataset.level));$('#intro').onclick=()=>intro(selectLevel);$('#back').onclick=selectChapter;}
function intro(next){view(`<div class="eyebrow">${chapterLabel()}</div><h2>${esc(text.chapter?.title||'桶狭間の戦い')}</h2><div class="muted">${esc(text.chapter?.year||'永禄3年（1560年）')}</div><div class="introArt" role="img" aria-label="${chapter===8?'大坂城へ駆ける真田幸村':chapter===7?'松尾山で決断を迫られる小早川秀秋':chapter===6?'燃える本能寺で蘭丸と立つ信長':chapter===5?'馬防柵の後ろで鉄砲隊を指揮する信長':chapter===4?'霧の川中島で相対する謙信と信玄':chapter===3?'山道で殿軍を指揮する秀吉':chapter===2?'月夜の墨俣で木材を運ぶ川並衆':'雨の桶狭間で騎兵を率いる信長'}"></div><div class="scroll"><p>${esc(text.chapter?.intro||'（紹介文）')}</p></div><button class="primary" id="next">つづける</button>`);$('#next').onclick=$('.introArt').onclick=()=>{progress.intro=true;save();next();};}
function enter(i){if(!UNLOCK_ALL&&!previewAll&&i>0&&!progress.stars[i-1])return;if(chapter>1&&!previewAll&&!store.isUnlocked()){unlockPage(()=>enter(i));return;}level=data.levels[i];deploy();}
function mini(l){const silhouette=l.initialMask||l.mask;return `<div class="formation" aria-label="陣形">${Array.from({length:56},(_,i)=>`<i class="${silhouette.includes(i)?'':'empty'}"></i>`).join('')}</div>`;}
