function effects(a,b,v,w,h,gap){const root=$('.board');const x=((a%7+b%7)/2)*(w+gap)+w/2,y=((Math.floor(a/7)+Math.floor(b/7))/2)*(h+gap)+h/2,n=document.createElement('div');n.className='float-name';n.textContent=short(v);n.style.left=x+'px';n.style.top=y+'px';root.appendChild(n);setTimeout(()=>n.remove(),1000);for(let k=0;k<12;k++){const im=document.createElement('img');im.src='fx/star.png';im.className='spark';im.style.left=x+'px';im.style.top=y+'px';im.style.setProperty('--dx',(Math.cos(k/12*6.28)*65)+'px');im.style.setProperty('--dy',(Math.sin(k/12*6.28)*65)+'px');root.appendChild(im);setTimeout(()=>im.remove(),700);}}
