let splashShown=false;
function title(){if(splashShown){home();return;}splashShown=true;view(`<button id="begin" class="splash-hit"><span class="splash-title">戦国二角取り</span><small>タップしてはじめる</small><em class="splash-progress">天下統一 ${conquered().size}/66</em></button>`,'splash');const splashToken=run;setTimeout(()=>{if(run===splashToken&&screen==='splash')$('#begin').onclick();},2000);$('#begin').onclick=home;}
function home(){const saved=readJSON('sengoku-session',null);if(validSession(saved)){view(`<h2>前回の続きから遊びますか？</h2><p>第${saved.chapter}章・第${saved.id}戦</p><div class="btn-row"><button id="fresh">最初から</button><button id="continue" class="primary">続ける</button></div>`,'center');$('#continue').onclick=()=>{if(saved.chapter>1&&!previewAll&&!store.isUnlocked()){unlockPage(()=>resumeSession(saved));return;}resumeSession(saved);};$('#fresh').onclick=()=>{localStorage.removeItem('sengoku-session');switchChapter(saved.chapter);enter(saved.id-1);};}else {if(localStorage.getItem('sengoku-session')){localStorage.removeItem('sengoku-session');toast('途中の一局を復元できません。戦績と購入記録は保持されています。');}currentCard();}}
function pageTab(key,choices,selected){return `<nav class="catalog-tabs page-tabs" aria-label="ページ">${choices.map(([id,label])=>`<button data-page-tab="${id}" aria-current="${id===selected?'page':'false'}">${label}</button>`).join('')}</nav>`;}
function savedTab(key,choices,value){const selected=(typeof value==='string'?value:null)??readJSON('sengoku-tabs',{})[key]??choices[0][0];return choices.some(c=>c[0]===selected)?selected:choices[0][0];}
function bindPageTabs(key,render){document.querySelectorAll('[data-page-tab]').forEach(b=>b.onclick=()=>{const tabs=readJSON('sengoku-tabs',{});tabs[key]=b.dataset.pageTab;localStorage.setItem('sengoku-tabs',JSON.stringify(tabs));render(b.dataset.pageTab);});}
let settingsReturn=null;
function settingsPage(tab){const choices=[['sound','音・表示'],['data','データ']];tab=savedTab('settings',choices,tab);view(`${meritCounter()}<header class="toolbar"><h2>設定</h2><button id="close-settings">戻る</button></header>${pageTab('settings',choices,tab)}${tab==='sound'?`${[['music','BGM（背景音楽）'],['sfx','効果音']].map(([key,label])=>`<div class="setting-row sound-row"><label for="${key}-volume">${label} <output id="${key}-value">${Math.round(settings[key]*100)}</output></label><input id="${key}-volume" aria-label="${label} 音量" type="range" min="0" max="100" step="1" value="${Math.round(settings[key]*100)}"><input id="${key}-enabled" aria-label="${label} 入・切" type="checkbox" role="switch" ${settings[key+'Enabled']?'checked':''}></div>`).join('')}<label class="setting-row">振動 <input id="vibration-setting" type="checkbox" role="switch" ${settings.vibration?'checked':''}></label><label class="setting-row">天気効果 <input id="weather-setting" type="checkbox" role="switch" ${settings.weather?'checked':''}></label><label class="setting-row">文字サイズ <button id="text-size">${settings.largeText?'大':'標準'} ▾</button></label><label class="setting-row">のんびりモード <input id="relaxed-setting" type="checkbox" role="switch" ${settings.relaxed?'checked':''}></label><p class="mode-explanation">時間制限なし（包囲・救出・手数の目標はあり）<br>星は2つまで。3つ目は通常モードで残り時間50％以上、献策・陣替えなしで獲得（自動は除く）。<br>通常モードで残り時間25％以上を保ってクリアすると時間の星を獲得。変更時は一局を最初から。</p>`:`<div class="settings-buttons"><button id="help">遊び方</button><button id="treasury">典藏${unread()?'<i class="red-dot"></i>':''}</button><button id="tutorial-again">チュートリアル</button><button id="about">このアプリについて</button><button id="erase">データ消去</button></div>`}`,'settings paged');$('#close-settings').onclick=()=>{const back=settingsReturn;settingsReturn=null;if(back)back();else deploy();};bindPageTabs('settings',settingsPage);if(tab==='sound'){const persist=()=>{localStorage.setItem(SETTINGS_KEY,JSON.stringify(settings));applySettings();};for(const key of ['music','sfx']){ $('#'+key+'-volume').oninput=e=>{settings[key]=Number(e.target.value)/100;$('#'+key+'-value').textContent=e.target.value;persist();};$('#'+key+'-enabled').oninput=e=>{settings[key+'Enabled']=e.target.checked;persist();};}for(const key of ['weather','vibration','relaxed'])$('#'+key+'-setting').oninput=e=>{settings[key]=e.target.checked;if(key==='relaxed')localStorage.removeItem('sengoku-session');persist();};$('#text-size').onclick=()=>choiceDialog('文字サイズ',[['standard','標準'],['large','大']],v=>{settings.largeText=v==='large';persist();settingsPage('sound');});return;}$('#treasury').onclick=openCollection;$('#help').onclick=()=>helpPage();$('#tutorial-again').onclick=()=>tutorialPage(settingsPage);
$('#about').onclick=()=>{view('<h2>このアプリについて</h2><p>戦国二角取り</p><p>効果音：<a href="https://soundeffect-lab.info/" target="_blank" rel="noopener">効果音ラボ</a><br>パーティクル：<a href="https://kenney.nl/assets/particle-pack" target="_blank" rel="noopener">Kenney Particle Pack（CC0）</a><br>武将・背景：AI生成素材を使用<br>地図：Ash_Crow／百楽兎（CC BY 2.5）、配色・構成を変更</p><button id="return">戻る</button>','settings');$('#return').onclick=settingsPage;};$('#erase').onclick=()=>{view('<h2>データを消去しますか？</h2><p>戦績・名鑑・途中の一局・戦功・陣屋の装いを消去します。購入記録は保持します。</p><div class="btn-row"><button id="cancel">キャンセル</button><button id="confirm-erase" class="danger">消去する</button></div>','settings');$('#cancel').onclick=settingsPage;$('#confirm-erase').onclick=()=>{for(const key of Object.keys(localStorage))if(key.startsWith('sengoku-')&&!['sengoku-store-v1','sengoku-mock-receipt'].includes(key))localStorage.removeItem(key);location.reload();};};}
function tutorialDiagram(n){const rows=[['同じ武将を二角以内で','▣ ━ ┓<br>　　 ┃<br>▣ ━ ┛'],['木材が上から補給される','▣ ▣ ▣<br>↓ ↓ ↓<br>□ □ □'],['敵の柵を血路で突破','▣ │ ▣<br>血路を開く ↓<br>▣ ━ ▣'],['隣の牌を消して霧を晴らす','▣ ▣ ？<br>消去 → ？が晴れる'],['消した行が左へ詰まる','▣ □ ▣<br>← ←<br>▣ ▣ □'],['火の手は手数で迫る','🔥 あと3手 → 2 → 1<br>燃える前に消去 → 鎖を防ぐ'],['小早川の寝返りに備える','寝返りまで 4 → 家康<br>0になると残る秀秋が家康に変わる'],['外堀なし・砲撃で回転','▣ ▣<br>↻ 2×2<br>▣ ▣']];const r=rows[n-1];return `<div class="tutorial-diagram"><b>${r[0]}</b><div>${r[1]}</div><small>○ 二角まで　× 牌の通り抜け</small></div>`;}
function tutorialPage(next,n=chapter){const c=chapters.get(n);view(`<h2>${n===1?'二角取りの遊び方':`第${n}章の新しい戦い方`}</h2>${tutorialDiagram(n)}<p>同じ武将を二枚つなぎます。曲がれるのは二回まで。ほかの牌は通り抜けられません。</p>${n>1?`<p>${Object.entries(c.text.rules||{}).filter(([k])=>!k.startsWith('target')&&k!=='boss').map(([,v])=>esc(v)).join('<br>')}</p>`:''}<button id="tutorial-done" class="primary">わかった</button>`,'settings');$('#tutorial-done').onclick=next;}
function tutorialIfNeeded(next){next();const key=`sengoku-tutorial-${chapter}`;if(level.id===1&&!localStorage.getItem(key)){spotlightTutorial(()=>localStorage.setItem(key,'1'));}else if(level.falling)smallTip('消すと、同じ列の牌が下に落ちます。');}
function helpPage(tab){const choices=[['basic','基本'],['strategy','計略'],['chapters','章のルール'],['merit','戦功・陣屋']];tab=savedTab('help',choices,tab);const n=Number(readJSON('sengoku-help-chapter',1)),c=chapters.get(n)||chapters.get(1);const relaxed=strategyHelp().split('\n').find(line=>line.startsWith('第'+n+'章：'))||'時間制限なし。時間の星・残り時間ボーナスは不計。';const rules=[...(n===1?['同じ武将を、二角以内でつなぎます。']:Object.values(c.text.rules||{})), 'のんびりモード：'+relaxed];const rp=pager('help-rules-'+n,rules.length);view(`<header class="toolbar"><h2>遊び方</h2><button id="help-back">戻る</button></header>${pageTab('help',choices,tab)}<div class="help-content">${tab==='basic'?`${tutorialDiagram(1)}<p>同じ武将を二枚つなぎます。曲がれるのは二回まで。ほかの牌は通れません。</p><p>二つ星：残り時間25％以上。三つ星：残り時間50％以上、献策・陣替えなし（自動陣替えは除く）。のんびりモードは二つ星まで。</p>`:tab==='strategy'?strategyHelp().split('<h3>のんびりモード</h3>')[0]:tab==='merit'?'<p>クリア・残り時間・連撃・ノーヒント・初クリアで戦功を獲得。</p><p>陣屋で牌の装い・盤の背景・家紋の色を交換できます。装いは強さに影響しません。</p>':`<nav class="chapter-pages">${[...chapters].map(([i])=>`<button data-help-chapter="${i}" aria-current="${i===n?'page':'false'}">${i}</button>`).join('')}</nav><h3>第${n}章 ${esc(c.text.chapter?.title)}</h3>${tutorialDiagram(n)}<p>${esc(rules[rp.index])}</p>${rp.html}<p class="muted">ルールを一つずつ確認できます。</p>`}</div>`,'settings paged help');$('#help-back').onclick=()=>settingsPage('data');bindPageTabs('help',helpPage);if(tab==='chapters')rp.bind(()=>helpPage('chapters'));document.querySelectorAll('[data-help-chapter]').forEach(b=>b.onclick=()=>{localStorage.setItem('sengoku-help-chapter',b.dataset.helpChapter);helpPage('chapters');});}
function extraCollection(tab){localStorage.setItem('sengoku-collection-tab',tab);localStorage.removeItem('sengoku-unread');const page=pager('art',chapters.size);view(`<header class="toolbar"><h2>典藏</h2><button id="extra-close">戻る</button></header><nav class="catalog-tabs"><button id="extra-people">武将</button><button id="extra-art">挿絵</button><button id="extra-form">陣形</button><button id="extra-music">音楽</button></nav>${tab==='music'?'<p>音楽の典藏は、今後の更新で登場します。</p>':page.html+[...chapters].slice(page.index,page.index+1).map(([n,c])=>`<section><h3>第${n}章 ${esc(c.text.chapter?.title)}</h3>${c.progress.stars.every(Boolean)?`<a href="img/ch${n}_intro.jpg" target="_blank"><img class="gallery-art" src="img/ch${n}_intro.jpg" alt="第${n}章の挿絵"></a>`:'<div class="locked-art">？？？<br>この章の十戦をクリアすると解放</div>'}</section>`).join('')}`,'collection paged');if(tab!=='music')page.bind(()=>extraCollection(tab));$('#extra-close').onclick=()=>settingsPage('data');$('#extra-people').onclick=collection;$('#extra-art').onclick=()=>extraCollection('art');$('#extra-form').onclick=formationCollection;$('#extra-music').onclick=()=>extraCollection('music');}
// Shown after the free chapter celebration; dismissing never opens a transaction.
function futureBattles(){
 const sketches=[['木材補給','<path d="M13 13h54v12H13zm0 18h54v12H13zM40 47v18m-8-8 8 8 8-8"/>'],['包囲網','<path d="M14 14h52v52H14zM8 27h64M8 53h64M27 8v64M53 8v64"/>'],['霧','<path d="M10 25h47M22 36h48M10 47h47M22 58h48"/>']];
 view(`<div class="eyebrow">第一章 制覇</div><h2>この先の戦い</h2><div class="future-sketches">${sketches.map(([label,paths])=>`<figure><svg viewBox="0 0 80 80" aria-hidden="true">${paths}</svg><figcaption>${label}</figcaption></figure>`).join('')}</div><p>全8章・80の戦い・武将名鑑・天下統一</p><p>第2章から第8章、新たな70の戦いへ。<br>一度の購入で全8章を永久に解放</p><small>武将名鑑と地図は第一章から楽しめます。<br>解放後も、戦いは順番に進みます。</small><div class="btn-row"><button id="future-later">あとで</button><button id="future-unlock" class="primary">全編を解放する</button></div>`,'center future-battles');
 $('#future-later').onclick=()=>{switchChapter(1);selectLevel();};
 $('#future-unlock').onclick=()=>unlockPage(()=>{switchChapter(2);enter(0);});
}
async function unlockPage(next){view('<h2>全編解放</h2><p>第一章の10戦は無料です。</p><p>全8章・80の戦い・武将名鑑・天下統一<br>一度の購入で全8章を永久に解放</p><p id="price">価格を確認中…</p><button id="purchase" class="primary">購入する</button><div class="btn-row"><button id="store-back">戻る</button><button id="restore">購入を復元</button></div><p id="store-status" role="status"></p>','settings');$('#store-back').onclick=()=>{switchChapter(1);level=data.levels[9];deploy();};const priceEl=$('#price');store.getPrice().then(price=>{priceEl.textContent=price;}).catch(()=>{priceEl.textContent='価格を取得できません';});for(const action of ['purchase','restore'])$('#'+action).onclick=async()=>{const buttons=[$('#purchase'),$('#restore')];buttons.forEach(b=>b.disabled=true);try{const result=await store[action]();if(result&&store.isUnlocked()){next();return;}$('#store-status').textContent=action==='restore'?'復元できる購入がありません。':'購入はキャンセルされました。';}catch{$('#store-status').textContent='処理できませんでした。もう一度お試しください。';}buttons.forEach(b=>b.disabled=false);};}
function saveSession(){if(screen!=='game'||busy||!board)return;try{localStorage.setItem('sengoku-session',JSON.stringify({version:1,tips:[...tipKeys],relaxed:settings.relaxed,chapter,id:level.id,board,ids,history,hints,shuffles,moves,combo,selected,lastMatchAge:lastMatch?performance.now()-lastMatch:null,maxCombo,usedHint,remaining:seconds(),queues,nextTileId,fire,fog,siege,shot,betrayalLeft,artilleryDelay:level.noOuter?Math.max(0,seconds()-artilleryDue):null,siegeDelay:level.siege?Math.max(0,seconds()-siegeDue):null,supplyDelay:level.construction?Math.max(0,seconds()-supplyDue):null}));}catch{}}
function resumeSession(s){if(!validSession(s)){localStorage.removeItem('sengoku-session');currentCard();toast('途中の一局を復元できません。戦績と購入記録は保持されています。');return false;}s=structuredClone(s);s.board=s.board.map(v=>v||0);s.history.forEach(t=>t.board=t.board.map(v=>v||0));s.nextTileId=Math.max(s.nextTileId,...s.ids.map(id=>id+1),...s.history.map(t=>Math.max(...t.ids)+1));settings.relaxed=!!s.relaxed;localStorage.setItem(SETTINGS_KEY,JSON.stringify(settings));switchChapter(s.chapter);level=data.levels[s.id-1];start();tipKeys=new Set(Array.isArray(s.tips)?s.tips.filter(v=>typeof v==='string'):[]);({board,ids,history,hints,shuffles,moves,maxCombo,usedHint,remaining,queues,nextTileId,fire,fog,siege,shot,betrayalLeft}=s);paused=false;started=performance.now();artilleryDue=remaining-s.artilleryDelay;siegeDue=remaining-s.siegeDelay;supplyDue=remaining-s.supplyDelay;combo=s.combo||0;selected=Number.isInteger(s.selected)?s.selected:-1;lastMatch=s.lastMatchAge===null?0:performance.now()-(s.lastMatchAge||0);render();updateHud();ensureMove();saveSession();}
setInterval(saveSession,250);window.addEventListener('pagehide',saveSession);

applySettings();
try{
 const catalogResponse=await fetch('text/catalog.json');if(!catalogResponse.ok)throw Error('catalog');catalog=await catalogResponse.json();loadCollection();
 for(const n of [1,2,3,4,5,6,7,8]){const response=await fetch(n===1?'data/levels.json':`data/levels_ch${n}.json`);if(!response.ok)throw Error('levels');const d=await response.json();let t={};try{const r=await fetch(['','text/ch1.json','text/ch2.json','text/ch3.json','text/ch4.json','text/ch5.json','text/ch6.json','text/ch7.json','text/ch8.json'][n]);if(r.ok)t=await r.json();}catch{}
 let p={stars:Array(10).fill(0),intro:false};try{const saved=JSON.parse(localStorage.getItem(`sengoku-ch${n}-v1`));if(Array.isArray(saved?.stars))p={stars:Array.from({length:10},(_,i)=>Math.min(3,Math.max(0,Number(saved.stars[i])||0))),intro:!!saved.intro};}catch{}chapters.set(n,{data:d,text:t,progress:p});}
 for(const c of chapters.values())for(const l of c.data.levels)if(c.progress.stars[l.id-1])collectDebut(c.data,l);
 worldMap=await fetch('data/map.json').then(r=>{if(!r.ok)throw new Error('地図を読み込めません');return r.json();});
 for(const v of worldMap.levels)chapters.get(v.chapter).data.levels[v.level-1].province=v.province;
 ({data,text,progress}=chapters.get(1));title();
}catch{app.innerHTML='<main class="screen center"><h2>読み込みに失敗しました</h2><p>HTTPサーバーから開き直してください。</p></main>';}

function meritCounter(value=readMerit(localStorage).balance){return `<div class="merit-counter" aria-label="現在の戦功">戦功 <b id="merit-count">${value}</b></div>`;}
function applyCosmetics(){const s=readMerit(localStorage);document.body.dataset.skin=s.selected.skin;document.body.dataset.board=s.selected.board;document.body.dataset.crest=s.selected.crest;}
function settlementHTML(r){return `<div class="settlement">${r.rows.map(([label,value],i)=>`<div class="merit-row" style="animation-delay:${.65+i*.4}s"><span>${label}</span><b>+${value}</b></div>`).join('')}</div>`;}
function animateMerit(r){const token=run;let sum=0;const later=(fn,ms)=>setTimeout(()=>{if(run===token)fn();},ms);r.rows.forEach((row,i)=>{for(let step=1;step<=8;step++)later(()=>{$('#merit-total').textContent=`戦功 +${sum+Math.floor(row[1]*step/8)}`;if(step===8)sum+=row[1];},650+i*400+step*35);});for(let i=0;i<10;i++)later(()=>{const origin=$('#merit-total').getBoundingClientRect(),target=$('.merit-counter').getBoundingClientRect();const coin=document.createElement('i');coin.className='merit-coin';coin.innerHTML='<svg viewBox="0 0 24 24"><g fill="none" stroke="#805317" stroke-width="1.5"><ellipse cx="12" cy="12" rx="8" ry="5"/><ellipse cx="12" cy="12" rx="5" ry="8"/><circle cx="12" cy="12" r="2"/></g></svg>';coin.style.left=origin.left+origin.width/2+'px';coin.style.top=origin.top+'px';coin.style.setProperty('--coin-x',target.left+target.width/2-origin.left-origin.width/2+'px');coin.style.setProperty('--coin-y',target.top-origin.top+'px');app.appendChild(coin);later(()=>{coin.remove();$('#merit-count').textContent=r.state.balance-r.total+Math.floor(r.total*(i+1)/10);$('#merit-count').animate?.([{transform:'scale(1.18)'},{transform:'scale(1)'}],{duration:160});if(i%3===0)sound('coin');},650);},2750+i*65);}
function campPage(tab){const choices=[['skin','牌の装い'],['board','盤の背景'],['crest','家紋の色']];tab=savedTab('camp',choices,tab);const s=readMerit(localStorage);view(`${meritCounter()}<header class="toolbar"><h2>陣屋</h2><button id="camp-back">戻る</button></header><p class="muted">戦功で装いを楽しむ。戦いの難しさは変わりません。</p>${pageTab('camp',choices,tab)}${choices.filter(([kind])=>kind===tab).map(([kind,label])=>`<h3>${label}</h3><div class="camp-grid">${GOODS.filter(g=>g.kind===kind).map(g=>`<button data-good="${g.id}" aria-pressed="${s.selected[kind]===g.id}" ${!s.owned.includes(g.id)&&s.balance<g.price?'disabled':''}>${kind==='skin'?`<span class="skin-sample" data-sample="${g.id}"><img src="${portrait(1)}" alt=""></span>`:''}<b>${g.name}</b><small>${s.selected[kind]===g.id?'装備中':s.owned.includes(g.id)?'装備する':s.balance<g.price?'戦功不足':'交換'}</small><span class="good-description">${kind==='skin'?'牌を彩る装い':kind==='board'?'盤に敷く背景':'家紋の彩り'} · ${g.price} 戦功</span></button>`).join('')}</div>`).join('')}<p class="muted">今後の装い：挿絵・音楽・武将の別年齢</p>`,'settings paged camp');bindPageTabs('camp',campPage);$('#camp-back').onclick=deploy;document.querySelectorAll('[data-good]').forEach(b=>b.onclick=()=>{try{if(redeemMerit(localStorage,b.dataset.good))campPage();else toast('戦功が足りません');}catch{toast('記録を保存できません');}});}

const STRATEGIES={hint:['献策','消せる組を一つ教えてくれる'],shuffle:['陣替え','牌を並べ替える'],undo:['引き鉦','直前の手順に戻る'],breakout:['血路','包囲の柵を一重取り払う']};
function icon(id){return `<img class="strategy-icon" src="img/icons/${id}.png" alt="">`;}
function strategyButton(id){const [name,help]=STRATEGIES[id];return `<button id="${id}" aria-label="${name}：${help}" title="${name}：${help}">${icon(id)}<span>${name}</span><b id="${id}-badge" class="strategy-badge"></b></button>`;}
function badge(id,count){$('#'+id+'-badge').textContent=count;}
function bindStrategyHelp(){for(const id of Object.keys(STRATEGIES)){const b=$('#'+id);if(!b)continue;let timer,held=false;const cancel=()=>clearTimeout(timer);b.addEventListener('pointerdown',()=>{held=false;timer=setTimeout(()=>{held=true;toast(STRATEGIES[id].join('：'));},500);});for(const e of ['pointerup','pointercancel','pointerleave'])b.addEventListener(e,cancel);b.addEventListener('click',e=>{if(held){e.stopImmediatePropagation();e.preventDefault();held=false;}},true);b.addEventListener('focus',()=>toast(STRATEGIES[id].join('：')));}}
function strategyHelp(){return `<h3>計略（長押しで説明）</h3><div class="strategy-help">${Object.entries(STRATEGIES).map(([id,[name,help]])=>`<p>${icon(id)}<b>${name}</b>：${help}</p>`).join('')}<p>${icon('pause')}床几：一時停止</p></div><h3>のんびりモード</h3><p>時間切れはありません。時間の星は不計、残り時間ボーナスはありません。
第1章：奇襲の手数条件は同じ。
第2章：2組消すごとに木材補給。決戦の夜明けは補給間隔を2手に換算（総組数の1.2倍以上）した手数が期限です。
第3章：2組ごとに包囲・補給。包囲による敗北と長政の条件は同じ。
第4章：霧と一騎打ち、補給は2組ごと。
第5章：左寄せと討伐の手数条件、補給は2組ごと。
第6章：炎と鎖は従来どおり手数で進行。秒の減点はありません。補給は2組ごと。
第7章：寝返りと討伐の手数条件は同じ。補給・包囲は2組ごと。
第8章：砲撃・補給は2組ごと。炎・寝返り・本陣の手数条件は同じ。
盤面が空なら木材はすぐに補給されます。</p>`;}

function choiceDialog(title,choices,next){const o=document.createElement('div');o.className='overlay';o.innerHTML=`<div class="dialog choice-dialog" role="dialog" aria-modal="true" aria-label="${esc(title)}"><h2>${esc(title)}</h2>${choices.map(([v,t])=>`<button data-choice="${v}">${esc(t)}</button>`).join('')}<button id="choice-cancel">戻る</button></div>`;app.appendChild(o);o.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{o.remove();next(b.dataset.choice);});$('#choice-cancel').onclick=()=>o.remove();}
function battleSettings(){saveSession();const saved=readJSON('sengoku-session',null);remaining=seconds();paused=true;settingsReturn=()=>{if(saved&&saved.relaxed===settings.relaxed)resumeSession(saved);else deploy();};settingsPage();}
function smallTip(message){if(tipKeys.has(message))return;tipKeys.add(message);const e=document.createElement('div');e.className='small-tip';e.textContent=message;app.appendChild(e);setTimeout(()=>e.remove(),3500);}
function spotlightTutorial(done){remaining=seconds();paused=true;music.pause(true);weather({paused:true});const steps=chapter===1?[['.tile','同じ武将を二枚、二角以内でつなぎます。'],['#hint','献策：つながる二枚を教えます。回数は毎戦決まっています。']]:[[level.siege?'#breakout':level.target||level.duel||level.fire||level.betrayal?'#target':'.tile',level.siege?'柵に囲まれたら「血路」で道を開けます。':'出陣で確かめた目標を、ここで追いながら進めます。']] ;let index=0;const show=()=>{const [selector,message]=steps[index],target=$(selector);target.classList.add('spotlight-target');const o=document.createElement('div');o.className='spotlight-overlay';const rect=target.getBoundingClientRect?.();o.innerHTML=`${rect?`<div class="spotlight-window" style="left:${rect.left-4}px;top:${rect.top-4}px;width:${rect.width+8}px;height:${rect.height+8}px"></div>`:''}<div class="spotlight-card" role="dialog" aria-modal="true"><span class="tutorial-arrow">${index?'↓':'↑'}</span><p>${message}</p><button id="spotlight-next">わかった</button></div>`;app.appendChild(o);$('#spotlight-next').onclick=()=>{target.classList.remove('spotlight-target');o.remove();if(++index<steps.length)show();else{done();paused=false;started=performance.now();music.pause(false);weather({paused:false});}};};show();}
